<?php require_once __DIR__.'/../../config/ui.php'; require_login('ADMIN'); $q=trim($_GET['q']??'');$st=$_GET['status']??'';$sql="SELECT * FROM usuarios WHERE perfil='ASSOCIADO'";$p=[];if($q!==''){$sql.=' AND (nome LIKE :q OR cpf LIKE :q OR matricula LIKE :q)';$p[':q']="%$q%";}if(in_array($st,['EM_DIA','DEVEDOR','DESFILIADO'],true)){$sql.=' AND status_financeiro=:st';$p[':st']=$st;}$sql.=' ORDER BY nome';$x=$pdo->prepare($sql);$x->execute($p);$rows=$x->fetchAll();admin_start('Associados','associados.php');?><div class="mb-8 flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><p class="mb-2 text-sm font-semibold text-blue-600">Gestão de membros</p><h2 class="text-3xl font-extrabold">Associados</h2><p class="mt-2 text-sm text-slate-500">Consulte e acompanhe toda a sua base.</p></div><div class="flex flex-wrap gap-3"><a href="<?=e(app_url('admin/importar_associados.php'))?>" class="rounded-lg border border-slate-200 bg-white px-5 py-3 text-sm font-bold text-slate-700">Importar planilha</a><a href="<?=e(app_url('admin/novo_associado.php'))?>" class="rounded-lg bg-blue-600 px-5 py-3 text-sm font-bold text-white hover:bg-blue-700">+ Novo associado</a></div></div><div class="shadow-soft rounded-xl border border-slate-100 bg-white p-5"><form class="mb-5 flex flex-col gap-3 md:flex-row"><input name="q" value="<?=e($q)?>" placeholder="Pesquisar por nome, CPF ou matrícula" class="flex-1 rounded-lg border border-slate-200 bg-slate-50 px-4 py-3 text-sm outline-none focus:border-blue-500"><select name="status" class="rounded-lg border border-slate-200 bg-slate-50 px-4 py-3 text-sm"><option value="">Todos os status</option><?php foreach(['EM_DIA'=>'Em dia','DEVEDOR'=>'Devedor','DESFILIADO'=>'Desfiliado'] as $v=>$l):?><option value="<?=$v?>" <?=$st===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select><button class="rounded-lg bg-slate-900 px-5 py-3 text-sm font-semibold text-white">Filtrar</button></form><div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="border-b border-slate-100 text-xs uppercase tracking-wider text-slate-400"><tr><th class="pb-4">Associado</th><th class="pb-4">Matrícula</th><th class="pb-4">CPF</th><th class="pb-4">Status</th><th class="pb-4 text-right">Ação</th></tr></thead><tbody><?php foreach($rows as $r):$ok=$r['status_financeiro']==='EM_DIA';?><tr class="border-b border-slate-50"><td class="py-4"><div class="flex items-center gap-3"><div class="grid h-10 w-10 place-items-center rounded-full bg-blue-100 font-bold text-blue-700"><?=e(strtoupper(substr($r['nome'],0,1)))?></div><div><b><?=e($r['nome'])?></b><p class="text-xs text-slate-400"><?=e($r['email'])?></p></div></div></td><td class="py-4 font-mono text-xs text-cyan-600"><?=e($r['matricula'])?></td><td class="py-4 text-slate-500"><?=e($r['cpf'])?></td><td class="py-4"><span class="rounded-full px-3 py-1 text-xs font-semibold <?=$ok?'bg-green-50 text-green-700':($r['status_financeiro']==='DEVEDOR'?'bg-amber-50 text-amber-700':'bg-red-50 text-red-700')?>"><?=e($ok?'Ativo':($r['status_financeiro']==='DEVEDOR'?'Pendente':'Desfiliado'))?></span></td><td class="py-4 text-right"><a href="<?=e(app_url('admin/perfil.php?id='.(int)$r['id']))?>" class="inline-flex rounded-lg bg-slate-100 px-4 py-2 text-xs font-semibold text-slate-700 hover:bg-blue-600 hover:text-white">Ver perfil</a></td></tr><?php endforeach;?></tbody></table><?php if(!$rows):?><p class="py-12 text-center text-sm text-slate-400">Nenhum associado encontrado.</p><?php endif;?></div></div><?php admin_end();